def teacher_content(f):
    link,flow=common.file_link,common.flow; c="#6b318f"
    data={1:("Evidence Inventory and Recovery","prepares d(8)(A-C)","INVENTORY","Inventory, one documented recovery, six-piece evidence map, conflict, and priority.","Missing old evidence triggers recovery, not automatic point loss. Preserve the inventory and recovery; trim workbook discussion first."),2:("Individual Career Plan","d(8)(A-C)","PLAN","Eight-section current plan with sources, uncertainty, actions, backup, and support.","No current Irving label becomes a guarantee. Preserve source labels and three actions; trim sharing first."),3:("Presentation Plan and Rehearsal","prepares d(4)(C)","PRESENT","Route/privacy plan, evidence sequence, two rehearsals, backup, and revision.","Do not require public speaking or high-production media. Trim decorative work first."),4:("Communicated Career Capstone","d(4)(C), d(8)(A-C)","DELIVERY","2-3-minute individual communicated evidence, feedback, revision, and transfer record.","Run parallel/private routes, not an impossible serial roster. Score evidence and organization, not accent, eye contact, camera, confidence, or polish."),5:("Final Course Reflection","d(8)(A), d(8)(C)","REFLECT","Specific then/now, six-weeks examples, five skill transfers, dated next action, and closing.","Specific evidence matters more than forced positivity. Celebration/share is optional and consent-based.")}
    out={}
    for d,(title,teks,key,evidence,monitor) in data.items():
        out[d]={"TITLE":title,"SUBTITLE":f"50 minutes · TEKS {teks}","ALERT":"<strong>Boundary:</strong> A missing old page, family interview, H&amp;L login, partner, or public-presentation route does not block the capstone. Recover current evidence and protect privacy.","PREP":f'<ul><li>Post {link(f[key]["id"],"the student packet")}, rubric as needed, and private activity.</li><li>Open the coordinated Student Guide.</li><li>Preassign recovery and communication routes.</li></ul>',"EVIDENCE":f"<p>{evidence}</p>","FLOW":flow(c,"Launch · 5","State the evidence job.")+flow("#4c8b38","Model · 8","One accurate bounded example.")+flow("#155d7a","Build · 22","Private evidence work.")+flow("#d39b22","Recover/rehearse/revise · 12","Make the route and revision visible.")+flow(c,"Exit · 3","One decision and next action."),"MONITOR":f"<p>{monitor}</p>","SUPPORT":"<p>Each major evidence job receives its own page. Short fields request labels only; every explanation has 4-9 full-width lines. Accept typing, dictation, annotation, enlarged print, paper, conference, recording, AAC, or authorized multimodal evidence.</p>","FALLBACK":"<p>No family adult, H&amp;L download, private screenshot, public speech, partner, camera, presentation platform, expensive design, class photo, personal contact/family data, or unsupported pathway guarantee is required.</p>"}
    out[4]["EVIDENCE"] = "<p><strong>Major 2 in the 6SW assessment map:</strong> 2–3-minute individual communicated evidence, feedback, revision, and transfer record. Convert the rubric result to a 100-point grade only after the Major group is verified.</p>"
    return out

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as client:
        module=await ensure_module(client); path="course files/CCR Materials/6SW/Wk6"; folder=await common.ensure_folder(client,path)
        names={"INVENTORY":"6sw-wk6-career-evidence-inventory.pdf","PLAN":"6sw-wk6-individual-career-plan.pdf","PRESENT":"6sw-wk6-capstone-presentation-plan.pdf","DELIVERY":"6sw-wk6-capstone-delivery-record.pdf","REFLECT":"6sw-wk6-final-course-reflection.pdf","RUBRIC":"6sw-wk6-capstone-rubric.pdf"}; files={k:await common.upload(client,ROOT/"docs/resources/worksheets"/n,path) for k,n in names.items()}
        vp="course files/CCR Materials/6SW/Wk6/Locked Licensed Visuals"; await common.ensure_folder(client,vp); visuals={f"p{n}":await common.upload(client,ASSETS/f"fyf-p{n}.jpg",vp) for n in [277,278,279,280,297,298,299,300]}
        assignments={}
        for d,key in {1:"INVENTORY",2:"PLAN",3:"PRESENT",5:"REFLECT"}.items(): assignments[d]=await common.upsert_assignment(client,TITLES[d],"<p>Complete privately by annotation, upload, typed labeled responses, dictation, or paper.</p>",["student_annotation","online_upload","online_text_entry"],files[key]["id"])
        assignments[4]=await common.upsert_assignment(client,TITLES[4],"<p>Submit private 2-3-minute communicated evidence through the authorized route plus the delivery/revision record. This is Major 2 in the 6SW map; keep unpublished/ungraded until the Major group and 60% weighting are verified.</p>",["media_recording","student_annotation","online_upload","online_text_entry"],files["DELIVERY"]["id"])
        urls={d:f"/courses/{COURSE_ID}/assignments/{a['id']}" for d,a in assignments.items()}; s,t=student_content(files,visuals,urls),teacher_content(files); labels={1:"Evidence Inventory and Recovery",2:"Individual Career Plan",3:"Presentation Plan and Rehearsal",4:"Communicated Career Capstone",5:"Final Course Reflection"}; order=[]; pages={}
        for d in range(1,6):
            ht=f"Day {d} · {labels[d]}"; h=await prior.upsert_item(client,module["id"],"SubHeader",None,ht); order.append(("SubHeader",h["id"],ht)); st=f"STUDENT: 6SW Wk6 Day {d} - {labels[d]}"; sp=await common.upsert_page(client,st,common.render("6sw-wk6-student.html",{"COURSE_ID":COURSE_ID,"DAY":d,**s[d]})); tt=f"TEACHER: 6SW Wk6 Day {d} Facilitator Guide"; tp=await common.upsert_page(client,tt,common.render("6sw-wk6-teacher.html",{"COURSE_ID":COURSE_ID,"DAY":d,"STUDENT_PAGE_URL":sp["url"],**t[d]})); await prior.upsert_item(client,module["id"],"Page",tp["url"],tt); await prior.upsert_item(client,module["id"],"Page",sp["url"],st); await prior.upsert_item(client,module["id"],"Assignment",assignments[d]["id"],TITLES[d]); order += [("Page",tp["url"],tt),("Page",sp["url"],st),("Assignment",assignments[d]["id"],TITLES[d])]; pages[d]={"teacher":tp,"student":sp}
        items=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items")
        for pos,(kind,key,title) in enumerate(order,1):
            item=next(i for i in items if (kind=="SubHeader" and i.get("id")==key) or (kind=="Page" and i.get("page_url")==key) or (kind=="Assignment" and i.get("content_id")==key)); await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{module['id']}/items/{item['id']}",data={"module_item[position]":pos,"module_item[title]":title})
        final=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items"); module=await common.api(client,"GET",f"/courses/{COURSE_ID}/modules/{module['id']}"); print(json.dumps({"module":{"id":module["id"],"published":module["published"]},"folder":{"id":folder["id"],"locked":folder["locked"]},"files":{k:x["id"] for k,x in files.items()},"visuals":{k:x["id"] for k,x in visuals.items()},"assignments":{str(k):{"id":x["id"],"published":x.get("published")} for k,x in assignments.items()},"pages":{str(d):{k:{"url":x["url"],"published":x["published"]} for k,x in p.items()} for d,p in pages.items()},"items":[{"position":i["position"],"type":i["type"],"title":i["title"]} for i in final]},indent=2))

if __name__=="__main__":asyncio.run(main())
